import{_ as e,o,c as d,a2 as n}from"./chunks/framework.CHX4lV2z.js";const p=JSON.parse('{"title":"Configuration Integration","description":"","frontmatter":{},"headers":[],"relativePath":"host-adapter-development/configuration-integration.md","filePath":"host-adapter-development/configuration-integration.md","lastUpdated":1791002220000}'),l={name:"host-adapter-development/configuration-integration.md"};function a(i,t,s,r,c,g){return o(),d("div",null,[...t[0]||(t[0]=[n('<h1 id="configuration-integration" tabindex="-1">Configuration Integration <a class="header-anchor" href="#configuration-integration" aria-label="Permalink to &quot;Configuration Integration&quot;">​</a></h1><h2 id="config-files-by-host" tabindex="-1">Config Files by Host <a class="header-anchor" href="#config-files-by-host" aria-label="Permalink to &quot;Config Files by Host&quot;">​</a></h2><p>From source:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Host</th><th style="text-align:left;">Config Location</th><th style="text-align:left;">Purpose</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>OpenClaw</strong></td><td style="text-align:left;">Plugin entry in <code>~/.openclaw/openclaw.json</code></td><td style="text-align:left;">TokenPilot registered as a plugin within OpenClaw configuration</td></tr><tr><td style="text-align:left;"><strong>Codex CLI</strong></td><td style="text-align:left;"><code>~/.codex/tokenpilot.json</code> (runtime config) + <code>~/.codex/hooks.json</code> (hook registration)</td><td style="text-align:left;"><code>tokenpilot.json</code> stores provider config and runtime settings. <code>hooks.json</code> registers hooks (<code>SessionStart</code>, <code>PreToolUse</code>, <code>PostToolUse</code>). Host&#39;s <code>config.toml</code> modified to reroute provider <code>base_url</code> to local proxy</td></tr><tr><td style="text-align:left;"><strong>Claude Code</strong></td><td style="text-align:left;"><code>~/.claude/tokenpilot.json</code> (runtime config) + <code>~/.claude/settings.json</code> (gateway routing) + <code>~/.claude/.claude.json</code> (MCP registration)</td><td style="text-align:left;"><code>tokenpilot.json</code> stores runtime config. <code>settings.json</code> updated for gateway routing. <code>.claude.json</code> registers <code>tokenpilot_memory_fault_recover</code> MCP server</td></tr><tr><td style="text-align:left;"><strong>pi</strong></td><td style="text-align:left;"><code>~/.pi/agent/tokenpilot.json</code> (+ extension loader at <code>~/.pi/agent/extensions/tokenpilot/index.js</code>)</td><td style="text-align:left;"><code>tokenpilot.json</code> stores runtime config. The loader is the only file install writes; no pi-owned config file is modified</td></tr><tr><td style="text-align:left;"><strong>OpenCode</strong></td><td style="text-align:left;"><code>~/.config/opencode/tokenpilot.json</code> (runtime config) + <code>~/.config/opencode/opencode.json</code> (recovery MCP registration) + <code>plugins/tokenpilot.js</code> (loader)</td><td style="text-align:left;"><code>tokenpilot.json</code> stores runtime config. <code>opencode.json</code> gains exactly one <code>mcp.tokenpilot_memory_fault_recover</code> entry, after a backup</td></tr><tr><td style="text-align:left;"><strong>DeepSeek Harness</strong></td><td style="text-align:left;">Selected Harness profile&#39;s <code>cordis.patch.yml</code></td><td style="text-align:left;"><code>tokenpilot-dsh</code> settings: master switch, durable <code>stateDir</code>, task-state estimator, eviction, and compaction ordering; see <a href="/LightRSI/hosts/deepseek-harness#configure-and-enable">configuration guide</a></td></tr></tbody></table><h2 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h2><p>From source:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Adapter</th><th style="text-align:left;">Environment Variable</th><th style="text-align:left;">Default Path</th></tr></thead><tbody><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;"><code>LIGHTRSI_OPENCLAW_HOME</code></td><td style="text-align:left;"><code>~/.openclaw/</code></td></tr><tr><td style="text-align:left;">OpenClaw</td><td style="text-align:left;"><code>OPENCLAW_CONFIG_PATH</code></td><td style="text-align:left;"><code>~/.openclaw/openclaw.json</code></td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;"><code>CODEX_CONFIG_PATH</code></td><td style="text-align:left;"><code>~/.codex/config.toml</code></td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;"><code>CODEX_HOOKS_CONFIG_PATH</code></td><td style="text-align:left;"><code>~/.codex/hooks.json</code></td></tr><tr><td style="text-align:left;">Codex</td><td style="text-align:left;"><code>TOKENPILOT_CODEX_CONFIG</code></td><td style="text-align:left;"><code>~/.codex/tokenpilot.json</code></td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;"><code>CLAUDE_CODE_SETTINGS_PATH</code></td><td style="text-align:left;"><code>~/.claude/settings.json</code></td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;"><code>CLAUDE_CODE_MCP_CONFIG_PATH</code></td><td style="text-align:left;"><code>~/.claude/.claude.json</code></td></tr><tr><td style="text-align:left;">Claude Code</td><td style="text-align:left;"><code>TOKENPILOT_CLAUDE_CODE_CONFIG</code></td><td style="text-align:left;"><code>~/.claude/tokenpilot.json</code></td></tr><tr><td style="text-align:left;">pi</td><td style="text-align:left;"><code>PI_CODING_AGENT_DIR</code></td><td style="text-align:left;"><code>~/.pi/agent/</code></td></tr><tr><td style="text-align:left;">pi</td><td style="text-align:left;"><code>TOKENPILOT_PI_CONFIG</code></td><td style="text-align:left;"><code>~/.pi/agent/tokenpilot.json</code></td></tr><tr><td style="text-align:left;">OpenCode</td><td style="text-align:left;"><code>TOKENPILOT_OPENCODE_CONFIG_DIR</code></td><td style="text-align:left;"><code>~/.config/opencode/</code></td></tr><tr><td style="text-align:left;">OpenCode</td><td style="text-align:left;"><code>TOKENPILOT_OPENCODE_CONFIG</code></td><td style="text-align:left;"><code>~/.config/opencode/tokenpilot.json</code></td></tr></tbody></table><h2 id="backup-strategy" tabindex="-1">Backup Strategy <a class="header-anchor" href="#backup-strategy" aria-label="Permalink to &quot;Backup Strategy&quot;">​</a></h2><p>Before modifying existing host config files, the OpenClaw, Codex, and Claude Code installers create <code>.tokenpilot.bak</code> backups. This applies to Codex (<code>~/.codex/config.toml</code>) and Claude Code (<code>~/.claude/settings.json</code>, <code>~/.claude/.claude.json</code>). The pi installer modifies no pi-owned file; the OpenCode installer writes a timestamped backup before adding its single MCP entry, and leaves a non-plain-JSON <code>opencode.json</code> or an <code>opencode.jsonc</code> untouched.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./adapter-architecture">Adapter Architecture</a></li><li><a href="./adding-new-host">Adding a New Host</a></li><li><a href="./hook-proxy-integration">Hook and Proxy Integration</a></li><li><a href="https://github.com/zjunlp/LightRSI/blob/main/README.md" target="_blank" rel="noreferrer">TokenPilot Configuration</a></li></ul>',11)])])}const x=e(l,[["render",a]]);export{p as __pageData,x as default};
